std::filesystem::path stream_state_projector::cache_path(const std::string &stream_key, const std::string &flow_key) const {
	std::uint64_t hash = 14695981039346656037ULL;
	for(unsigned char ch : json::array({stream_key, flow_key}).dump()) {
		hash ^= ch;
		hash *= 1099511628211ULL;
	}
	std::ostringstream name;
	name << std::hex << std::setfill('0') << std::setw(16) << hash;
	return m_cfg.root_dir / "inactive-cache" / name.str().substr(0, 2) / (name.str() + ".json");
}

json stream_state_projector::load_inactive(const std::string &stream_key, const std::string &flow_key) const {
	const auto path = cache_path(stream_key, flow_key);
	if(!std::filesystem::exists(path)) return nullptr;
	std::ifstream input(path);
	json cached;
	if(!input || !(input >> cached) || cached.value("stream_key", std::string{}) != stream_key ||
	   cached.value("flow_key", std::string{}) != flow_key || !cached.at("state").is_object()) {
		throw std::runtime_error("invalid inactive state cache: " + path.string());
	}
	const double expires = m_cfg.retention_hours == 0 ? 0.0 : inactive_time(cached["state"]) + m_cfg.retention_hours * 3600.0;
	if(expires > 0.0 && expires <= m_state_time) return nullptr;
	if(cached.value("archived_at", 0.0) > m_state_time) {
		throw std::runtime_error("inactive state cache is newer than runtime state: " + path.string());
	}
	return std::move(cached["state"]);
}

